entries.text:
/* HOME-WORKSPACE-01: Owner-approved compact rows. Scoped to home only;
   layered important selectors defeat TASK-10's older white recovery cards.
   No hidden-state rules or price/calculation selectors are changed. */
@layer nomad360-palette-important {
 body:has(#home-screen) #home-screen #nomad360-home-secondary.nomad-workspace {
  display:block!important; margin:14px 0 0!important;padding:clamp(14px,3.4vw,22px)!important;
  background-color:#173B58!important;border:1px solid #38678B!important;border-radius:14px!important;
  box-shadow:none!important; color:#FFFFFF!important;min-width:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-heading{
  color:#FFFFFF!important;font:700 clamp(22px,5vw,28px)/1.2 var(--nd-font,Inter,sans-serif)!important;
  margin:0 0 14px!important;letter-spacing:-.025em!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-group-label{
  color:#FFFFFF!important;font:600 16px/1.35 var(--nd-font,Inter,sans-serif)!important;
  margin:12px 0 2px!important;padding:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-saved:not(:has(>.nomad-recovery-card:not([hidden]):not(.hidden))){
  display:none!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-card:not([hidden]):not(.hidden),
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-demo-item{
  display:grid!important;grid-template-columns:42px minmax(0,1fr) auto!important;
  gap:10px!important;align-items:center!important;min-width:0!important;
  padding:15px 0!important;margin:0!important;border:0!important;
  border-radius:0!important;background-color:transparent!important;box-shadow:none!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-card[hidden],
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-card.hidden{
  display:none!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-card:not(:first-of-type),
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-demo-item + .nomad-workspace-demo-item{
  border-top:1px solid #38678B!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-saved .nomad-recovery-card:first-of-type{
  border-top:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-icon {
  display:flex!important;align-items:center!important;justify-content:center!important;
  width:42px!important;height:42px!important;border-radius:10px!important;
  background-color:#38678B!important;color:#FFFFFF!important;flex-shrink:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-icon svg{
  display:block!important;width:23px!important;height:23px!important;
  fill:none!important;stroke:#FFFFFF!important;stroke-width:1.8!important;
  stroke-linecap:round!important;stroke-linejoin:round!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-body,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-info{
  min-width:0!important;padding:0!important;margin:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-title{
  display:block!important;color:#FFFFFF!important;font:700 clamp(15px,3.7vw,18px)/1.28 var(--nd-font,Inter,sans-serif)!important;
  margin:0!important;overflow-wrap:break-word!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-title,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-note,
 body:has(#home-screen) #home-screen #nomad360-home-secondary #portfolio-v2-linked-resume-home .nomad-recovery-detail,
 body:has(#home-screen) #home-screen #nomad360-home-secondary #portfolio-v2-resume-home .nomad-recovery-detail{
  display:none!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-detail,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-subtitle{
  display:block!important;color:#FFFFFF!important;
  font:400 clamp(12px,3vw,14px)/1.4 var(--nd-font,Inter,sans-serif)!important;
  margin:4px 0 0!important;overflow-wrap:anywhere!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-action,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-example-link{
  display:inline-flex!important;justify-content:flex-end!important;align-items:center!important;
  min-height:44px!important;min-width:76px!important;width:auto!important;max-width:110px!important;
  flex-shrink:0!important;padding:6px 1px!important;margin:0!important;border:0!important;
  border-radius:0!important;background-color:transparent!important;box-shadow:none!important;
  text-decoration:none!important;font-size:0!important;color:#FF913F!important;
  cursor:pointer!important;white-space:nowrap!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-action::before,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-example-link::before{
  content:attr(data-workspace-action)!important;color:#FF913F!important;
  font:600 clamp(12px,3.4vw,15px)/1.25 var(--nd-font,Inter,sans-serif)!important;
  white-space:nowrap!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-action::after,
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-example-link::after{
  content:"›"!important;color:#FF913F!important;font:400 27px/1 sans-serif!important;
  margin-left:5px!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary :is(.nomad-recovery-action,.nomad-example-link):focus-visible{
  outline:2px solid #FF913F!important;outline-offset:2px!important;border-radius:4px!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-example-row{
  display:block!important;padding:0!important;margin:0!important;
  border:0!important;background-color:transparent!important;min-width:0!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-demos{
  margin-top:12px!important;border-top:1px solid #38678B!important;padding-top:10px!important;
 }
 body:has(#home-screen) #home-screen #nomad360-selling-choice .nomad-choice-grid{
  display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:8px!important;
  grid-auto-rows:1fr!important;
 }
 body:has(#home-screen) #home-screen #nomad360-selling-choice .nomad-choice-button{
  background-color:#FF913F!important;color:#173B58!important;border:1px solid #FF913F!important;
  min-height:58px!important;min-width:0!important;padding:9px 6px!important;
  display:flex!important;justify-content:center!important;align-items:center!important;
  font:700 clamp(13px,3vw,18px)/1.2 var(--nd-font,Inter,sans-serif)!important;
  text-align:center!important;overflow-wrap:break-word!important;
 }
 body:has(#home-screen) #home-screen #nomad360-selling-choice .nomad-choice-button:hover:not(:disabled){
  background-color:#FF913F!important;color:#173B58!important;
 }
 body:has(#home-screen) #home-screen #business-currency-settings{
  margin-top:14px!important;background-color:#173B58!important;color:#FFFFFF!important;
  border:1px solid #38678B!important;border-radius:14px!important;
 }
 body:has(#home-screen) #home-screen #business-currency-settings #business-currency-question{
  color:#FFFFFF!important;font:700 clamp(17px,4vw,22px)/1.25 var(--nd-font,Inter,sans-serif)!important;
 }
 body:has(#home-screen) #home-screen #business-currency-settings #business-currency-help{
  font-size:13px!important;line-height:1.4!important;color:#FFFFFF!important;
 }
}
@media(max-width:390px){
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-recovery-card:not([hidden]):not(.hidden),
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-demo-item{
  grid-template-columns:36px minmax(0,1fr) auto!important;gap:8px!important;
 }
 body:has(#home-screen) #home-screen #nomad360-home-secondary .nomad-workspace-icon{
  width:36px!important;height:36px!important;
 }
}

@layer nomad360-palette-important {
 body:has(#home-screen) #home-screen #nomad360-selling-choice .nomad-choice-button {font-size:0!important;}
 body:has(#home-screen) #home-screen #nomad360-selling-choice .nomad-choice-button::after {
  content:attr(data-workspace-short)!important;display:block!important;
  font:700 clamp(13px,3vw,18px)/1.2 var(--nd-font,Inter,sans-serif)!important;
  color:#173B58!important;white-space:normal!important;text-align:center!important;
 }
}
